import{_ as t,V as e,W as o,X as p,Z as n,a1 as s,$ as c,Y as l,F as i}from"./framework-b1bd8911.js";const u={},d=n("p",null,"将 markdown 文档转换为 html，算是很多业务场景里的基础能力，比如博客系统渲染文章、支持 markdown 语法的评论功能等，都在用它",-1),r=l(`<p>要自己从零实现一个 markdown 语法解析器，工作量可不小；好在开源世界里已经有很多现成的轮子，markdown-plugin 选的是 <code>flexmark</code>（之前看开源博客系统 Solo 源码的时候接触到的包），本篇就来讲一下这个插件在它基础上封装出来的 <code>MarkDown2HtmlWrapper</code> 怎么用</p><h2 id="_1-依赖引入" tabindex="-1"><a class="header-anchor" href="#_1-依赖引入" aria-hidden="true">#</a> 1. 依赖引入</h2><blockquote><p>项目已发布到 maven 中央仓库，直接依赖即可</p></blockquote><p>maven 项目在 pom.xml 中添加依赖，建议使用最新版本：</p><div class="language-xml line-numbers-mode" data-ext="xml"><pre class="language-xml"><code><span class="token comment">&lt;!-- https://mvnrepository.com/artifact/com.github.liuyueyi.media/markdown-plugin --&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>dependency</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>groupId</span><span class="token punctuation">&gt;</span></span>com.github.liuyueyi.media<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>groupId</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>artifactId</span><span class="token punctuation">&gt;</span></span>markdown-plugin<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>artifactId</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>version</span><span class="token punctuation">&gt;</span></span>3.1.0<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>version</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>dependency</span><span class="token punctuation">&gt;</span></span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>gradle 项目则在 build.gradle 中添加：</p><div class="language-groovy line-numbers-mode" data-ext="groovy"><pre class="language-groovy"><code><span class="token comment">// https://mvnrepository.com/artifact/com.github.liuyueyi.media/markdown-plugin</span>
implementation <span class="token string">&#39;com.github.liuyueyi.media:markdown-plugin:3.1.0&#39;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>这个插件内部已经把 flexmark（当前版本 0.62.2）、xhtmlrenderer、nekohtml 这些依赖都打好了，我们只管用就行，不需要再单独引入 flexmark 三件套</p><h2 id="_2-设计思路" tabindex="-1"><a class="header-anchor" href="#_2-设计思路" aria-hidden="true">#</a> 2. 设计思路</h2><p>先想一下我们期望的调用姿势：给我一段 markdown 文本（文件、网络、字符串都行），还我一个 html</p><p>所以封装的核心就是两件事：</p><ul><li>输入源的适配：文件、url、流、纯文本，四种入口统一收口到一个转换方法</li><li>输出结果不只是 html 字符串，还得带样式：转换出来的裸 html 是没有 css 的，丢到页面上或者渲染成图片都不好看，所以返回值里得把 css 也一起带上</li></ul><p>于是就有了返回值 <code>MarkdownEntity</code>，它比一个单纯的 html 字符串多了两样东西：</p><ul><li><code>css</code>：默认加载插件内置的 <code>md/huimarkdown.css</code> 样式</li><li><code>divStyle</code>：html 内容外层包了一个 <code>&lt;div&gt;</code> 标签，这个 map 里维护的就是这个 div 的属性，可以往里面塞统一的宽高、字体、class 等</li></ul><p>最后 toString 的时候，把 css 和带属性的 div 拼在 html 外面：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token annotation punctuation">@Override</span>
<span class="token keyword">public</span> <span class="token class-name">String</span> <span class="token function">toString</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> css <span class="token operator">+</span> <span class="token string">&quot;\\n&lt;div &quot;</span> <span class="token operator">+</span> <span class="token function">parseDiv</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">+</span> <span class="token string">&quot;&gt;\\n&quot;</span> <span class="token operator">+</span> html <span class="token operator">+</span> <span class="token string">&quot;\\n&lt;/div&gt;&quot;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_3-使用姿势" tabindex="-1"><a class="header-anchor" href="#_3-使用姿势" aria-hidden="true">#</a> 3. 使用姿势</h2><h3 id="_3-1-四种输入入口" tabindex="-1"><a class="header-anchor" href="#_3-1-四种输入入口" aria-hidden="true">#</a> 3.1 四种输入入口</h3><p><code>MarkDown2HtmlWrapper</code> 提供了四个静态方法，覆盖了常见的输入姿势：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">// 从本地文件读取（支持相对路径，或 &quot;/&quot; 开头的 classpath 路径）</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">MarkdownEntity</span> <span class="token function">ofFile</span><span class="token punctuation">(</span><span class="token class-name">String</span> path<span class="token punctuation">)</span> <span class="token keyword">throws</span> <span class="token class-name">IOException</span>

<span class="token comment">// 从网络读取 markdown 文件</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">MarkdownEntity</span> <span class="token function">ofUrl</span><span class="token punctuation">(</span><span class="token class-name">String</span> url<span class="token punctuation">)</span> <span class="token keyword">throws</span> <span class="token class-name">IOException</span>

<span class="token comment">// 从输入流读取</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">MarkdownEntity</span> <span class="token function">ofStream</span><span class="token punctuation">(</span><span class="token class-name">InputStream</span> stream<span class="token punctuation">)</span> <span class="token keyword">throws</span> <span class="token class-name">IOException</span>

<span class="token comment">// 直接传 markdown 语义的文本</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">MarkdownEntity</span> <span class="token function">ofContent</span><span class="token punctuation">(</span><span class="token class-name">String</span> content<span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>最简单的使用，就是从文件中读取 markdown 内容然后转换，三行搞定：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token annotation punctuation">@Test</span>
<span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">markdown2html</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">throws</span> <span class="token class-name">IOException</span> <span class="token punctuation">{</span>
    <span class="token class-name">String</span> file <span class="token operator">=</span> <span class="token string">&quot;md/tutorial.md&quot;</span><span class="token punctuation">;</span>
    <span class="token class-name">MarkdownEntity</span> html <span class="token operator">=</span> <span class="token class-name">MarkDown2HtmlWrapper</span><span class="token punctuation">.</span><span class="token function">ofFile</span><span class="token punctuation">(</span>file<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span>html<span class="token punctuation">.</span><span class="token function">toString</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>如果 markdown 内容本来就在内存里（比如用户提交的评论），直接用 <code>ofContent</code>：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token class-name">String</span> md <span class="token operator">=</span> <span class="token string">&quot;### 标题\\n\\n- item1\\n- item2\\n\\n&gt; 一段引用文字&quot;</span><span class="token punctuation">;</span>
<span class="token class-name">MarkdownEntity</span> entity <span class="token operator">=</span> <span class="token class-name">MarkDown2HtmlWrapper</span><span class="token punctuation">.</span><span class="token function">ofContent</span><span class="token punctuation">(</span>md<span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// 拿到纯 html 片段</span>
<span class="token class-name">String</span> html <span class="token operator">=</span> entity<span class="token punctuation">.</span><span class="token function">getHtml</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token comment">// 拿到完整的带 css 和外层 div 的内容</span>
<span class="token class-name">String</span> full <span class="token operator">=</span> entity<span class="token punctuation">.</span><span class="token function">toString</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>注意 <code>ofStream</code> 内部是用 <code>StandardCharsets.UTF_8</code> 读取的，所以只要你的输入源本身是 utf-8 编码，中文不会出问题</p><h3 id="_3-2-底层的-flexmark-配置" tabindex="-1"><a class="header-anchor" href="#_3-2-底层的-flexmark-配置" aria-hidden="true">#</a> 3.2 底层的 Flexmark 配置</h3><p>上面四个入口最终都会走到 <code>parse</code> 方法，这里面就是 flexmark 的标准用法：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token doc-comment comment">/**
 * markdown to html
 *
 * <span class="token keyword">@param</span> <span class="token parameter">content</span> markdown contents
 * <span class="token keyword">@return</span> parse html contents
 */</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">String</span> <span class="token function">parse</span><span class="token punctuation">(</span><span class="token class-name">String</span> content<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token class-name">MutableDataSet</span> options <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">MutableDataSet</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    options<span class="token punctuation">.</span><span class="token function">setFrom</span><span class="token punctuation">(</span><span class="token class-name">ParserEmulationProfile</span><span class="token punctuation">.</span><span class="token constant">MARKDOWN</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// enable table parse!</span>
    options<span class="token punctuation">.</span><span class="token function">set</span><span class="token punctuation">(</span><span class="token class-name">Parser</span><span class="token punctuation">.</span><span class="token constant">EXTENSIONS</span><span class="token punctuation">,</span> <span class="token class-name">Arrays</span><span class="token punctuation">.</span><span class="token function">asList</span><span class="token punctuation">(</span><span class="token class-name">TablesExtension</span><span class="token punctuation">.</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>


    <span class="token class-name">Parser</span> parser <span class="token operator">=</span> <span class="token class-name">Parser</span><span class="token punctuation">.</span><span class="token function">builder</span><span class="token punctuation">(</span>options<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token class-name">HtmlRenderer</span> renderer <span class="token operator">=</span> <span class="token class-name">HtmlRenderer</span><span class="token punctuation">.</span><span class="token function">builder</span><span class="token punctuation">(</span>options<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token class-name">Node</span> document <span class="token operator">=</span> parser<span class="token punctuation">.</span><span class="token function">parse</span><span class="token punctuation">(</span>content<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">return</span> renderer<span class="token punctuation">.</span><span class="token function">render</span><span class="token punctuation">(</span>document<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>两个关键配置说一下：</p><ul><li><code>options.setFrom(ParserEmulationProfile.MARKDOWN)</code>：解析风格设置为标准 MARKDOWN</li><li><code>options.set(Parser.EXTENSIONS, Arrays.asList(TablesExtension.create()))</code>：加载表格扩展插件，没有这个，<code>| a | b |</code> 这种表格语法是解析不出来的</li></ul><p>默认情况下插件只加载了 tables 这一个扩展，如果还需要其他扩展语法（比如删除线、任务列表、GFM 风格的自动链接等），可以自己仿照 <code>parse</code> 方法，往 <code>Parser.EXTENSIONS</code> 里追加对应的扩展，flexmark 官方提供了 <code>flexmark-ext-gfm-strikethrough</code>、<code>flexmark-ext-gfm-tasklist</code> 等一堆扩展包，按需引入即可</p><h3 id="_3-3-换一套-css-主题" tabindex="-1"><a class="header-anchor" href="#_3-3-换一套-css-主题" aria-hidden="true">#</a> 3.3 换一套 css 主题</h3><p>默认的 <code>MD_CSS</code> 是插件启动时从内置资源 <code>md/huimarkdown.css</code> 读取的，长在 <code>MarkDown2HtmlWrapper</code> 的一个静态变量上：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">String</span> <span class="token constant">MD_CSS</span> <span class="token operator">=</span> <span class="token keyword">null</span><span class="token punctuation">;</span>

<span class="token keyword">static</span> <span class="token punctuation">{</span>
    <span class="token constant">MD_CSS</span> <span class="token operator">=</span> <span class="token function">buildCssContent</span><span class="token punctuation">(</span><span class="token string">&quot;md/huimarkdown.css&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>如果你不喜欢这个默认样式，插件里还内置了几套主题 css（在插件的 resources 目录下）：<code>heyrain.css</code>、<code>hyper.css</code>、<code>koala.css</code>、<code>huimarkdown_code.css</code>，可以用 <code>buildCssContent</code> 自己换：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token class-name">MarkdownEntity</span> entity <span class="token operator">=</span> <span class="token class-name">MarkDown2HtmlWrapper</span><span class="token punctuation">.</span><span class="token function">ofFile</span><span class="token punctuation">(</span><span class="token string">&quot;md/tutorial.md&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token comment">// 用 heyrain 主题替换默认的 huimarkdown 样式</span>
entity<span class="token punctuation">.</span><span class="token function">setCss</span><span class="token punctuation">(</span><span class="token class-name">MarkDown2HtmlWrapper</span><span class="token punctuation">.</span><span class="token function">buildCssContent</span><span class="token punctuation">(</span><span class="token string">&quot;md/heyrain.css&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>buildCssContent</code> 做的事情就是读文件然后包一层 <code>&lt;style type=&quot;text/css&quot;&gt;</code> 标签；你也可以传一个自己写的 css 文件路径进去，一样的效果</p><h3 id="_3-4-markdownentity-的其他玩法" tabindex="-1"><a class="header-anchor" href="#_3-4-markdownentity-的其他玩法" aria-hidden="true">#</a> 3.4 MarkdownEntity 的其他玩法</h3><p><code>MarkdownEntity</code> 上还有两个值得了解的方法：</p><p><strong>addDivStyle</strong>：往最外层的 div 上追加属性。默认情况下，<code>ofContent</code> 会给 div 加一个 <code>class=&quot;markdown-body &quot;</code>，好让内置 css 里的 <code>.markdown-body</code> 选择器能生效：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">// 默认行为</span>
entity<span class="token punctuation">.</span><span class="token function">addDivStyle</span><span class="token punctuation">(</span><span class="token string">&quot;class&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;markdown-body &quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token comment">// 也可以自己再追加别的，比如：</span>
entity<span class="token punctuation">.</span><span class="token function">addDivStyle</span><span class="token punctuation">(</span><span class="token string">&quot;style&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;width:600px;&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>addWidthCss</strong>：给指定标签批量加宽度限制的 css，内部模板长这样：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">String</span> <span class="token constant">TAG_WIDTH</span> <span class="token operator">=</span> <span class="token string">&quot;&lt;style type=\\&quot;text/css\\&quot;&gt; %s { width:85%%} &lt;/style&gt;&quot;</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>比如 <code>entity.addWidthCss(&quot;img&quot;)</code> 就是让 html 里所有的图片最大宽度为 85%，防止大图撑破容器。这个方法在转图片的链路里会被自动调用，后面讲 markdown 转图片的时候会再提到</p><h2 id="_4-常见坑" tabindex="-1"><a class="header-anchor" href="#_4-常见坑" aria-hidden="true">#</a> 4. 常见坑</h2><h3 id="_4-1-表格没有渲染出来" tabindex="-1"><a class="header-anchor" href="#_4-1-表格没有渲染出来" aria-hidden="true">#</a> 4.1 表格没有渲染出来</h3><p>自己单独用 flexmark 的时候，最容易踩的就是这个坑：表格语法原样输出成文本，并没有变成 <code>&lt;table&gt;</code>。原因就是默认的 Parser 没加载表格扩展，必须显式加 <code>TablesExtension.create()</code>。用 markdown-plugin 的话这一点已经处理好了，不用担心</p><h3 id="_4-2-直接-gethtml-没有样式" tabindex="-1"><a class="header-anchor" href="#_4-2-直接-gethtml-没有样式" aria-hidden="true">#</a> 4.2 直接 getHtml() 没有样式</h3><p><code>getHtml()</code> 拿到的只是 markdown 解析后的裸 html 片段，css 在 <code>entity.getCss()</code> 里。如果想得到一个能直接在浏览器里打开显示样式的完整内容，要用 <code>entity.toString()</code>，它会把 css + 带属性的 div + html 一起拼出来</p><h3 id="_4-3-ofurl-的地址格式" tabindex="-1"><a class="header-anchor" href="#_4-3-ofurl-的地址格式" aria-hidden="true">#</a> 4.3 ofUrl 的地址格式</h3><p><code>ofUrl</code> 底层还是走的 <code>FileReadUtil.getStreamByFileName(url)</code>，传的是 <code>http</code> 开头的完整 url 就能正常拉取；但要注意目标文件得是公网可访问的，而且这个方法没有复杂的鉴权、重定向处理，特殊场景建议自己先下载成流再用 <code>ofStream</code></p><h2 id="_5-小结" tabindex="-1"><a class="header-anchor" href="#_5-小结" aria-hidden="true">#</a> 5. 小结</h2><p>本篇介绍了 markdown 转 html 的基本使用，四种输入入口 + 默认样式 + 自定义主题；不过光转成 html 只算完成了一半，很多场景下（比如图文消息推送）我们最终要的是一张图片，这就得靠下一篇的 <code>Html2ImageWrapper</code> 登场了</p><p><strong>项目地址：</strong></p>`,54),k={href:"https://github.com/liuyueyi/quick-media",target:"_blank",rel:"noopener noreferrer"},m=n("li",null,[n("code",null,"QuickMedia"),s(" 目标是创建一个专注图文，音视频，二维码处理的开源项目")],-1);function v(h,g){const a=i("ExternalLinkIcon");return e(),o("div",null,[d,p(" more "),r,n("ul",null,[n("li",null,[n("a",k,[s("https://github.com/liuyueyi/quick-media"),c(a)])]),m])])}const y=t(u,[["render",v],["__file","01.markdown转html.html.vue"]]);export{y as default};
